@[simp] theorem matrixEntry_restrict (p : BanachExponent) {k N : ℕ}
    (α τ : Fin k ↪ Fin N) (A : FiniteMatrixBlock 𝕜 p N) (i j : Fin k) :
    matrixEntry p i j (matrixRestrict p α τ A) = matrixEntry p (α i) (τ j) A

